return {["FacingDeathSolo"]={["1"]={["action"]=[[$n身形灵巧随意，只是稍稍侧身偏头，轻松将攻击化解于无形之中。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n脚步迅而飘逸，若即若离，身影翩跹之际让人无从捉摸他的真正所在之处。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n在$N攻来时身形忽而隐去，再凝神仔细看去，便已出现在五步开外。]],["id"]=3,["textColor"]=[[RAN]]}},["PeachBlossomSound"]={["1"]={["action"]=[[$n见$N使出一招直冲面门当即使一式「颤韵」，随即头摆向一侧巧妙化解。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n见$N来势凶猛使出一式「幻音」，只见$n身形一闪似有幻影飘忽不定让$N攻势落空。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$N看准时机朝$n双腿下盘攻来，$n见势使出一式「鸣律」，随即双腿快速后撤将其躲避。]],["id"]=3,["textColor"]=[[RAN]]}},["Sheet1"]={["1"]={["action"]=[[攻势将近，只见$n身随意转，使出一招「鹤戏水」，飘然俯身将攻势尽数化去。]],["anim"]=[[Emjfdodge_head]],["hitPos"]=[[head]],["id"]=1,["offset"]=0,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n施展出一招「云中鹤」，身形潇洒飘逸地往后撤去，转眼便拉开丈余距离。]],["anim"]=[[Emjfdodge_chest]],["hitPos"]=[[chest]],["id"]=2,["offset"]=0,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n身轻如羽，飘然而起，一个轻灵的起落便躲过了凌厉的一击。]],["anim"]=[[Emjfdodge_foot]],["hitPos"]=[[foot]],["id"]=3,["offset"]=0,["textColor"]=[[RAN]]}},["StepFogShadowless"]={["1"]={["action"]=[[$N来势凶猛，$n当即使出一招「化雾」，只见$n身形如雾般飘忽不定让$N攻势落空。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n一招「驾雾」，身影虚闪，步伐摇曳不定，叫$N难寻其踪。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$N直取$n要害，只见$n凝神聚气，使出一招「腾云」，须臾间便已在数丈之外。]],["id"]=3,["textColor"]=[[RAN]]}},["UncertainDeadAlive"]={["1"]={["action"]=[[$n直取$N面门，只见$N仰面而倒，$n扑了个空。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[=[$n使出一招[躲风]，身形虚闪，叫$N难觅其踪。]=],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[=[$n抓准时机向$N下盘攻来，$N忙使出一招[藏形]，身影瞬时后撤。]=],["id"]=3,["textColor"]=[[RAN]]}},["anyingfuxiang"]={["1"]={["action"]=[[$n一个「月上柳梢头」，随着$N的攻势飘起，从容躲过这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n使出一招「大漠孤烟直」，猛然纵起丈余，结果$N扑了个空。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n身形一摇，幻出几个人影，一招「碎影舞斜阳」躲过了$N的攻势。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一招「燕子三抄水」纵身跃起，倏忽已落至$N身后。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n左一摇，右一晃，一招「云深不知处」已轻松闪过。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n双足一点，斜斜飞起，使出「斜日杏花飞」已闪到$N身侧。]],["id"]=6,["textColor"]=[[CYN]]}},["calmTideStepWaves"]={["1"]={["action"]=[[$n当即用出一式「潺流」，下一瞬身体一动头向后倾躲过了致命一击。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n见势用出一式「幻涟」，随即身形如同鬼魅虚晃一闪将其招数化解。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n不敢懈怠当即用出一式「微波」将内力汇聚双腿之上，霎那间动作轻巧灵活，将攻势化解。]],["id"]=3,["textColor"]=[[RAN]]}},["canghubu"]={["1"]={["action"]=[[只见$n施展一招RAN「藏头露尾」NOR，飞一般向后掠去，片刻间拉开了数丈距离。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n一招RAN「东躲西藏」NOR，身形左冲右突，来回摇摆，闪过迎面的攻击。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[恍惚间，$n戛然不动，仔细一看，原来只是一道虚影，而$n的真身早已不知去向。]],["id"]=3,["textColor"]=[[RAN]]},["4"]={["action"]=[[$n健步如飞，双眼牢牢盯住对手，随意一个起落便化解了对手的攻势。正是一招RAN「明枪易躲」NOR。]],["id"]=4,["textColor"]=[[RAN]]}},["cangxueguyingshi"]={["1"]={["action"]=[[PNK$n一招「雪鹰悄立」，在身周凝聚一股寒气，随即身形飞速腾挪，以寒气滞慢$N攻势，使自身立于不败之地。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[PNK$n身形下沉，施展一招「振翅双飞」，身体向左右循环偏侧，转瞬便避开了$N的连环攻势。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[PNK$n身子下沉，双手上扬，随即飞身高高掠起，如飞鹰腾空，速度极快无比，$N的刚猛攻势尽数落空！]],["id"]=3,["textColor"]=[[RAN]]}},["chanchubufa"]={["1"]={["action"]=[[只见$n一招「蟾飞九天」，身体向上笔直地纵起丈余，躲过了$N这一招。]],["anim"]=[[dodge-ccbf_foot]],["hitPos"]=[[foot]],["id"]=1,["offset"]=-150,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是$n一个使出「蛙鸣震天」，身形飘忽，轻轻一纵，早已避开。]],["anim"]=[[dodge-ccbf_foot]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-175,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一招「蛙入稻田」，身行随意转，倏地往一旁挪开了三尺，避过了这一招。]],["anim"]=[[dodge-ccbf_chest]],["hitPos"]=[[chest]],["id"]=3,["offset"]=-200,["textColor"]=[[CYN]]},["4"]={["action"]=[[可是$n一个「蟾蜍扑虫」，侧身一让，$N这一招扑了个空。]],["anim"]=[[dodge-ccbf_head]],["hitPos"]=[[head]],["id"]=4,["offset"]=-1,["textColor"]=[[CYN]]},["5"]={["action"]=[[却见$n「蟾翻白肚」，足不点地，往旁窜开数尺，躲了开去。]],["anim"]=[[dodge-ccbf_chest]],["hitPos"]=[[chest]],["id"]=5,["offset"]=-200,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n身形一招「金蟾归月」，身形微晃，有惊无险地避开了$N这一招。]],["anim"]=[[dodge-ccbf_head]],["hitPos"]=[[head]],["id"]=6,["offset"]=-10,["textColor"]=[[CYN]]}},["chilianlingbo"]={["1"]={["action"]=[[只见$n身形一转，凌空使出一式「赤练摆尾」，脚下步伐摇曳不定，令$N难触其分毫。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n凝神聚气，须臾间使出一记「腾蛇乘雾」，脚步既似舞蹈，又似躲闪，身影四散叫人难寻真身。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[只见$n悄无声息，不紧不慢地向后退去，仿佛片刻后身影就要融入黑暗之中。竟是一记「暗里猩红」！]],["id"]=3,["textColor"]=[[RAN]]}},["chuanhuaraoshu"]={["1"]={["action"]=[[$n一式GRN「斜燕归林去」NOR，身体如雨燕投林般直滑出丈余。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式MAG「花蝶戏蕊心」NOR，忽然一弯腰，全身凌空而行，顿时闪过了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式HIY「黄雀啄叶露」NOR，足不动，手不抬，一转眼间便绕到了$N的身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式GRN「青蜂弄花粉」NOR，一转身间，四面八方飘动着无数个$n的身影，令$N手足无措。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式HIW「蜓尾点水舞」NOR，长袖一拂，全身化为一道白影，幽幽地从$N头顶飘落。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n一式MAG「知了藏影踪」NOR，身行倏的从$N的眼前飘过，长发一甩，潇洒之极。]],["id"]=6,["textColor"]=[[CYN]]}},["dingzibu"]={["1"]={["action"]=[[$n漫不经心的向左迈出一步，刚好避过$N的凌厉攻势。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[可是$n恰巧往右走了一步，躲过了$N这一招。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[可是$n侧身一让，$N这一招扑了个空。]],["id"]=3,["textColor"]=[[RAN]]}},["douzhuanxingyi"]={["1"]={["action"]=[[只见$n身随意转，一式PNK「移星换斗」NOR，身子微微一侧，便将攻势化为无形。]],["anim"]=[[dodge-yxmt_chest]],["hitPos"]=[[head]],["id"]=1,["offset"]=-125,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n真气运转，含胸撤步，一式PNK「参横斗转」NOR施展开来，便与敌人拉开丈余距离，险之又险地将攻势尽数躲开。]],["anim"]=[[dodge-yxmt_head]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-175,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n忽而双足腾空，身若飘絮，一式PNK「欺天夺星」NOR，轻飘飘的一个起落便躲过了凌厉一击。]],["anim"]=[[dodge-yxmt_foot]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-200,["textColor"]=[[RAN]]}},["feiyanhuixiang"]={["1"]={["action"]=[[$n两臂鹏举，纵上丈余，一式「巨鹏亮翅」顿时避开了$N的凌厉攻势。,]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n身随风飘，侧身向后倒纵，轻巧地一式「风送紫霞」，化解了$N的攻势。,]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式「燕徊朝阳」，长袖飘飘身形晃动，一转眼间便绕到了$N的身后。,]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n低头恭身，抱拳一式「却别苍松」，身子向后滑出，将$N的攻势化于无形。,]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n使出「旭日初升」，笔直跃起，在半空中化为「金雁横空」，飘落到一旁。,]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n一招「晚月朗星」，身形左右急速晃动，幻出数个身影，从容地破解$N的攻势。,]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n含笑飘身使出「幻眼云湮」，身形幻成一道白影，轻飘飘地闪到$N的左侧。,]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n凝气守中一招「苍龙盘岭」，身化长龙绕着$N急转，使其无从下手，攻势不攻自破。,]],["id"]=8,["textColor"]=[[CYN]]}},["feiyingshisanshi"]={["1"]={["action"]=[[$n一招「迷影无踪」，身形飞逝如电，竟躲过了$N的猛烈攻势。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n一招「月半寒纱」，双手轻抚，身形来去如电，一时之间直教对手看不出自身所在。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n一招「影飞片羽」，跃至半空，身形急转，似退实进，转眼欺近$N身旁。]],["id"]=3,["textColor"]=[[RAN]]}},["fengshenjue"]={["1"]={["action"]=[[只见$n使出HIC「洛神凌波」NOR，衣诀飘飘，脚下如凌波踏水，快速几步，已避开攻击。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是$n使出HIW「凌空虚度」NOR，提气纵起，在空中连跨七步，已在$N数丈之外。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一招HIY「布法行云」NOR，脚踏子午，掌分阴阳，不经意间避过$N这一招。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[可是$n一个HIC「风起云涌」NOR，身形如被大风所吹，飘飘优悠落到$N身后。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[却见$n使出GRN「春风拂柳」NOR，一足脚尖点地，身如弱柳，俯仰不定，$N这招可落了空。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n使出YEL「秋风萧瑟」NOR，一手捂胸，挺身前行，大有壮士一去不复返之势，$N被其气势所慑，只得退开。]],["id"]=6,["textColor"]=[[CYN]]}},["flowCloudsInkSils"]={["1"]={["action"]=[[$n见$N来势汹汹，使出一式「望月」，随机头一偏，躲过了致命一击。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n身体一侧，使出一式「移山」，$N招式擦衣而过，被你躲开。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n见$N击出一招瞬间后撤，使出一式「潮退」，$N击向$n要害的一招落空，化险为夷。]],["id"]=3,["textColor"]=[[RAN]]}},["fuguanglueying"]={["1"]={["action"]=[[只见$n一招BLU「似来还往」NOR，双脚一前一后，似进又腿，在$n一愣间躲过了攻击。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是$n使出CYN「蜻蜓点水」NOR，脚尖站地，身形东倒西歪间，破天冲起。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一招HIY「飞黄腾达」NOR，身随意转，刹那间在原地转了七八十圈，突然往地上一坐，原是转晕了，却使$N落了空。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[可是$n一个HIW「白驹过隙」NOR，身形微侧，提气直纵，躲过$N攻击。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[却见$n使出HIW「浮光掠影」NOR，在原地留下一个幻象，真身躲到了一边。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n身形一顿，HIB「逝者如斯」NOR，身形平平掠出，在空中留下一道弧形。]],["id"]=6,["textColor"]=[[CYN]]}},["getWetLotusSprout"]={["1"]={["action"]=[[$n见$N击出一招直冲要害当即用出一式「风拂」，下一瞬$n身体一动头向后倾躲过了致命一击。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$N使出一招向$n击来，见势$n用处一式「莲开」，随即身形一晃将其招数化解。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[见$N使出一招，$n不敢懈怠当即用出一式「碧波」将内力汇聚双腿之上，霎那间动作轻巧灵活，将攻势化解。]],["id"]=3,["textColor"]=[[RAN]]}},["gouyao"]={["1"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[wolf-dodge]],["hitPos"]=[[head]],["id"]=1,["offset"]=-199,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[wolf-dodge]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-199,["textColor"]=[[CYN]]},["3"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[wolf-dodge]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-199,["textColor"]=[[CYN]]}},["guisha"]={["1"]={["action"]=[[$N只觉眼前一花，不见了$n的身影。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n的身影渐渐暗淡，竟从$N眼前消失]],["id"]=2,["textColor"]=[[RAN]]}},["guiyoushenfa"]={["1"]={["action"]=[[$n一招RAN「鬼魅伎俩」NOR轻轻巧巧地避了开去。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[只见$n身影一晃，一式RAN「鬼神莫测」NOR早已避在七尺之外。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出RAN「鬼影遁形」NOR，轻轻松松地闪过。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n左足一点，一招RAN「鬼出电入」NOR腾空而起，避了开去。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[可是$n使一招RAN「鬼影遁形」NOR，身子轻轻飘了开去。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n身影微动，已经藉一招RAN「神出鬼没」NOR轻轻闪过。]],["id"]=6,["textColor"]=[[CYN]]}},["hidingSkyStride"]={["1"]={["action"]=[[$N的攻势凌厉非常，忽地袭向$n面门，然而$n却似已预见一切，身体一侧，头一偏，巧妙地避开了致命的一击。]],["anim"]=[[hcdodge_chest]],["hitPos"]=[[chest]],["id"]=1,["offset"]=0,["textColor"]=[[RAN]]},["2"]={["action"]=[=[$n眼神一凝，瞬息间使出一式[柳隐]，身形飘摇不定似风中柳，叫$N的攻击尽数落空。]=],["anim"]=[[hcdodge_foot]],["hitPos"]=[[foot]],["id"]=2,["offset"]=0,["textColor"]=[[RAN]]},["3"]={["action"]=[[$N的攻击势不可遏地袭向$n的下盘，然$n的身影却如烟云消散，只留下一阵淡淡的残影。]],["anim"]=[[hcdodge_head]],["hitPos"]=[[head]],["id"]=3,["offset"]=0,["textColor"]=[[RAN]]}},["huaxuyin"]={["1"]={["action"]=[[PNK只见$n一招「通於圣道」，身形翩跹而起，躲过了$N这一招。NOR]],["anim"]=[[qfsf_1]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-150,["textColor"]=[[RAN]]},["2"]={["action"]=[[PNK$n一式「别有之国」，身形晃动，一道虚影向一旁飘出。NOR]],["anim"]=[[dodge-sxbb_chest]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-175,["textColor"]=[[RAN]]},["3"]={["action"]=[[PNK$n使出「乐生」，一个抹身向后腾挪，避开了$N的凌厉攻势。NOR]],["anim"]=[[qfsf_2]],["hitPos"]=[[chest]],["id"]=3,["offset"]=-150,["textColor"]=[[RAN]]},["4"]={["action"]=[[PNK$n一招「恶死」，身随意转，$N只觉眼前一花，$n已飘然而去、躲开了所有攻击。NOR]],["anim"]=[[dodge-sxbb_chest]],["hitPos"]=[[chest]],["id"]=4,["offset"]=-175,["textColor"]=[[RAN]]}},["invisibleShadow"]={["1"]={["action"]=[[$n当即用出一式「潺流」，下一瞬身体一动头向后倾躲过了致命一击。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n见势用出一式「幻涟」，随即身形如同鬼魅虚晃一闪将其招数化解。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n不敢懈怠当即用出一式「微波」将内力汇聚双腿之上，霎那间动作轻巧灵活，将攻势化解。]],["id"]=3,["textColor"]=[[RAN]]}},["jiangshibufa"]={["1"]={["action"]=[[但是$n身形飘忽，轻轻一纵，也不见举手投足，轻而易举的避开这一击。]],["anim"]=[[dodge-jsbf_chest]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-110,["textColor"]=[[MAG]]},["2"]={["action"]=[[$n身子笔挺，膝盖不弯，僵直着往旁窜开数尺，躲了开去。]],["anim"]=[[dodge-jsbf_head]],["hitPos"]=[[head]],["id"]=2,["offset"]=-90,["textColor"]=[[MAG]]},["3"]={["action"]=[[$n身形往上拔起，犹如吊死鬼一般，直挺挺在空中一个旋转落在数尺之外。]],["anim"]=[[dodge-jsbf_foot]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-200,["textColor"]=[[MAG]]}},["jibenqinggong"]={["1"]={["action"]=[[但是和$p$l偏了几寸。]],["anim"]=[[barehand-dodge-head]],["hitPos"]=[[head]],["id"]=1,["offset"]=-200,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[barehand-dodge-chest]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-199,["textColor"]=[[CYN]]},["3"]={["action"]=[[但是$n身子一侧，闪了开去。]],["anim"]=[[barehand-dodge-foot]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-198,["textColor"]=[[CYN]]},["4"]={["action"]=[[但是被$p及时避开。]],["anim"]=[[barehand-dodge-head]],["hitPos"]=[[head]],["id"]=4,["offset"]=-197,["textColor"]=[[CYN]]},["5"]={["action"]=[[但是$n已有准备，不慌不忙的躲开。]],["anim"]=[[barehand-dodge-head]],["hitPos"]=[[head]],["id"]=5,["offset"]=-196,["textColor"]=[[CYN]]}},["jinyangong"]={["1"]={["action"]=[[$n足尖在地面一点，身形拔地而起，躲开了这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[却不料$n身形一转，突然转到了$N的身后。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n随着$N攻来的招式飘了起来，就如一片微风中的柳絮一般。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n身形左一晃、右一闪，不知怎么的，从攻击的间隙中钻了出来。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n足不点地地围绕$N连绕三个大圈，把$N这一招避了开去。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[但是$n一招「瑶光音迟」使出，早已绕到$N身後！]],["id"]=6,["textColor"]=[[CYN]]}},["kuihuafeiying"]={["1"]={["action"]=[[突然$n对着$N轻轻吹了口气，$N只觉得香风扑面，忙向后纵出丈许避开。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$N只觉眼前白光一闪，$n的人影已经站在两丈开外，$N的招式全部打在空处。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n身子一晃，$N的眼前顿时出现了四个$n的身形，当真不知哪个是真哪个是假。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n身形一转，向后闪出尺余，在电光火石之间逼过了$N的攻击。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$N只觉眼前一花，似乎见到$n身形一幌，但随即又见$n回到原地，却似从未离开。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$N眼睛一花，便没了$n的踪影。回头一看，$n已经站在$N的身后。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n一声长笑，身子倒纵出去，已离开$N有三丈远近，侧头向$N瞪视，一言不发。]],["id"]=7,["textColor"]=[[CYN]]}},["lingboweibu"]={["1"]={["action"]=[[HIR$n足下一个踉跄，乘势向左斜出半步，恰符合了虚步太清中RAN「忽焉纵体」NOR的步子，闪了开来。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[YEL$n身随意转，倏地往一旁挪开了三尺，避过了这一招。]],["anim"]=[[dodge-lbwb_foot]],["hitPos"]=[[chest]],["id"]=10,["offset"]=-75,["textColor"]=[[CYN]]},["11"]={["action"]=[[GRN可是$n侧身一让，$N这一招扑了个空。]],["anim"]=[[dodge-lbwb_foot]],["hitPos"]=[[head]],["id"]=11,["offset"]=-125,["textColor"]=[[CYN]]},["12"]={["action"]=[[HIG却见$n足不点地，往旁窜开数尺，躲了开去。]],["anim"]=[[dodge-lbwb_foot]],["hitPos"]=[[foot]],["id"]=12,["offset"]=-175,["textColor"]=[[CYN]]},["13"]={["action"]=[[HIW$n身形微晃，有惊无险地避开了$N这一招。]],["anim"]=[[dodge-lbwb_foot]],["hitPos"]=[[chest]],["id"]=13,["offset"]=-350,["textColor"]=[[CYN]]},["2"]={["action"]=[[HIC$n使出RAN「流风回雪」NOR歪歪斜斜退了几步，似乎不成章法，却在间不容缓的空隙中躲过了$N的攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[HIB$N的招式明明可以把$n围住，不知怎的，$n一式RAN「轻云蔽月」NOR，又如鬼魅般的跨出了圈外]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[HIW$n一式RAN「以遨以嬉」NOR，瞻之在前，忽焉在后，$N招式的落点和$n身子间总有厘毫之差。]],["anim"]=[[dodge-lbwb_chest]],["hitPos"]=[[chest]],["id"]=4,["offset"]=-150,["textColor"]=[[CYN]]},["5"]={["action"]=[[HIY$n身形闪处，突然转向，使出了RAN「神光离合」NOR，$N加紧攻势，竟无法碰到$n一片衣角。]],["anim"]=[[dodge-lbwb_chest]],["hitPos"]=[[head]],["id"]=5,["offset"]=-100,["textColor"]=[[CYN]]},["6"]={["action"]=[[HIC$n大喝一声，使出RAN「乍阴还阳」NOR，左足向右踏出，不料踏实之时，身子已在西北角上。]],["anim"]=[[dodge-lbwb_chest]],["hitPos"]=[[foot]],["id"]=6,["offset"]=-300,["textColor"]=[[CYN]]},["7"]={["action"]=[[HIG$n一式RAN「飘忽若神」NOR，侧身斜进，抢步“既济”，立闪“未济”，闪得几闪，已欺到$N的身后。]],["anim"]=[[dodge-lbwb_chest]],["hitPos"]=[[chest]],["id"]=7,["offset"]=-200,["textColor"]=[[CYN]]},["8"]={["action"]=[[HIG$n一式RAN「体迅飞枭」NOR，似乎自管自地踏步，毫不理会，每一步都踏在别人意想不到的所在。]],["anim"]=[[dodge-lbwb_chest]],["hitPos"]=[[head]],["id"]=8,["offset"]=-300,["textColor"]=[[CYN]]},["9"]={["action"]=[[RED但是$n身形飘忽，轻轻一纵，早已避开。]],["anim"]=[[dodge-lbwb_foot]],["hitPos"]=[[foot]],["id"]=9,["offset"]=-25,["textColor"]=[[CYN]]}},["lingxubu"]={["1"]={["action"]=[[$n一式HIW「雪地莲花」NOR，身子掣忽一转，$N只觉的眼前一花，失去了目标。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式HIY「一狐冲天」NOR，双脚点地，身子突然拔高了丈许，缓缓飘落在$N身后。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式CYN「移行幻影」NOR，身行一晃，顿时无数条身影一下子出现在$N的面前。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式MAG「狡兔三窟」NOR，飘然向后一退，躲开$N的凌厉攻势。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式BLU「烟雨飘渺」NOR，身体急转，化为一道白光，虚幻不定的出现在$N的周围。]],["id"]=5,["textColor"]=[[CYN]]}},["meixuepiaox"]={["1"]={["action"]=[[$n一式RAN「冰消雪融」NOR，一下滑到丈外开去，把$N攻势化於无形。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[却见$n伸手往地上遥遥一拍,一式RAN「梅飘九宵」NOR,如柳絮般轻轻飘起,躲过了这招。]],["id"]=10,["textColor"]=[[CYN]]},["11"]={["action"]=[[$n长笑一声,一式RAN「寒梅傲雪」NOR,长身而起,一时四面八方都是$n的影子,虚虚实实,不知哪个才是真的。]],["id"]=11,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n使出RAN「金狮狂舞」NOR，一个筋斗从$N头上一翻而过，$N打$n不着。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n脚步虚踩，忽左而右，使出RAN「雪入黄河」NOR从$N的腋下穿到$P身後。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n微笑中後退两步，身子一顿，一式RAN「飞雪藏形」NOR躲过$N这一击。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n掉转身子，轻轻一跃，一式RAN「狮子摇头」NOR轻描淡写地化开$N这一招。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n身子向上一纵，使出一式RAN「踏雪无痕」NOR跃起数尺，飘然落到一旁。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[但是$n轻笑一声,回身高拨而起,一式RAN「红梅飘雪」NOR,轻轻闪过了这招。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n随意转身,一招RAN「檀板金樽」NOR,如舞乐般飘身而上,避过了这招。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[只见$n身形一旋,拨身而起,使出RAN「梅月黄昏」NOR,整个人都失去了踪影,令$N扑了个空。]],["id"]=9,["textColor"]=[[CYN]]}},["mingyugong"]={["1"]={["action"]=[[$N身形加速，电光挪移，饶是$n攻击范围既广且厉，却总能在间不容发的空隙避过。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$N空中快速转折，在$n每次攻击前又倏乎消失，一下子就脱出$n的攻击范围。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$N只觉眼前一花，只见到$n身形一幌，自己的招数居然莫名其妙就落空了。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$N凭著高速身法，在$n的攻击范围内进退趋避，险险闪过一道又一道的攻击。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$N腾挪快速，竟然在空中形成身影残像，有如无数$N一起挪动。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n眼前忽然一花，眼前$N的身影似乎有些淡化，而另外一个$N竟尔出现在面前不足一尺的近处。]],["id"]=6,["textColor"]=[[CYN]]}},["niaozhuo"]={["1"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[bird-dodge]],["hitPos"]=[[head]],["id"]=1,["offset"]=-199,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[bird-dodge]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-198,["textColor"]=[[CYN]]},["3"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[bird-dodge]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-197,["textColor"]=[[CYN]]}},["piaomiaoshenfa"]={["1"]={["action"]=[[只见$n身随意转，一扭身已飘到$N背后，躲过了这一招。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[$n腾空一跃，双脚凌空虚踏，一招“魔冲霄汉”，躲开数尺。]],["id"]=10,["textColor"]=[[CYN]]},["11"]={["action"]=[[$n身形晃动，一招“魔心穹隆”，全身化作无数虚影掠出丈外。]],["id"]=11,["textColor"]=[[CYN]]},["12"]={["action"]=[[$n猛吸一口气，一招“奇魔异形”，身形以一个无比怪异的姿势扭曲着弹开数尺。]],["id"]=12,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n运起天魔身法，身影有如疾电流窜，令$N的攻势全数落空。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$N只感眼前一花，$n已幻化成无数化身四散飞射。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n身影突如陀螺急转，形成猛烈的气劲漩涡，坚密如墙，$N根本无从入手。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一招“魔幻虚影”，全身化出千百个身影躲闪开了$N这一招。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n气聚丹田，一招“重生魔寐”，身形急缩，躲开$N那致命一击。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n真气荡漾，清啸连连，一招“魔魇懵懵”，滑出丈外。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n双脚轻踏九曲，一招“魔光旖旎”，身形无比美妙地荡开数尺。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n使出如意人魔连环八步中的“魔影娉婷”，身形化实为虚地躲开了$N这一招。]],["id"]=9,["textColor"]=[[CYN]]}},["piaoyibufa"]={["1"]={["action"]=[[$n一个HIC「银鹭渡海」NOR，跃起数尺，躲过了$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n身形向后一纵，使出一招HIY「玉兔落尘」NOR，避过了$N的攻击。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出HIY「锦鲤穿沙」NOR，恰好躲过了$N的攻势。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一招MAG「灵狐幻遁」NOR，姿态美妙地躲了开去。]],["id"]=4,["textColor"]=[[CYN]]}},["pixiejianfa"]={["1"]={["action"]=[[突然之间，白影急幌，$n向后滑出丈余，立时又回到了原地，躲过了$N这一招。]],["id"]=1,["textColor"]=[[RAN]]},["10"]={["action"]=[[$n不挡不闪，左手食指颤动，向$N的左目急刺，竟是两败俱伤的打法！]],["id"]=10,["textColor"]=[[RAN]]},["11"]={["action"]=[[$n左拨右挡，兀自好整以暇的啧啧对$N连赞：“好功夫，好功夫！]],["id"]=11,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n手臂回转，在$N手肘下一推，顺势闪到一旁。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n右手伸出，在$N手腕上迅速无比的一按，顺势跳到一旁。]],["id"]=3,["textColor"]=[[RAN]]},["4"]={["action"]=[[$n身形飘忽，有如鬼魅，转了几转，移步到$N的身后，躲过了$N这一招。]],["id"]=4,["textColor"]=[[RAN]]},["5"]={["action"]=[[$N只觉眼前一花，似乎见到$n身形一幌，但随即又见$n回到原地，却似从未离开。]],["id"]=5,["textColor"]=[[RAN]]},["6"]={["action"]=[[$N眼睛一花，$n已没了踪影。突然$n从身后拍了一下$N的头，轻轻跃开。]],["id"]=6,["textColor"]=[[RAN]]},["7"]={["action"]=[[$n嫣然一笑，诡异之极，$N竟不知如何是好，停住了攻击。]],["id"]=7,["textColor"]=[[RAN]]},["8"]={["action"]=[[$n左一拨，右一拨，上一拨，下一拨，将$N的招数尽数拨开。这四下拨挡，周身竟无半分破绽。]],["id"]=8,["textColor"]=[[RAN]]},["9"]={["action"]=[[$n右手大拇指和食指捏住一根绣花针，向上一举，挡住来势，$N的招式便使不下去。]],["id"]=9,["textColor"]=[[RAN]]}},["qiankundanuoyi"]={["1"]={["action"]=[[$n使出WHT「避字决」NOR，浑身内力一震，身体后倾，顿感面门劲风阵阵，化险为夷。]],["anim"]=[[dodge-yynyg_head]],["hitPos"]=[[head]],["id"]=1,["offset"]=0,["textColor"]=[[RAN]]},["2"]={["action"]=[[危急之时，$n用出一招WHT「退字诀」NOR，当即运转周身内力，急速向后退去，$N始料未及，招式落空。]],["anim"]=[[dodge-yynyg_chest]],["hitPos"]=[[chest]],["id"]=2,["offset"]=0,["textColor"]=[[RAN]]},["3"]={["action"]=[[$N招式将近，情急之下，$n使出WHT「移字诀」NOR，霎那间便出现在另一侧，原地则似有一道残影，很是诡秘。]],["anim"]=[[dodge-yynyg_foot]],["hitPos"]=[[foot]],["id"]=3,["offset"]=0,["textColor"]=[[RAN]]}},["qianlongfeidun"]={["1"]={["action"]=[[PNK$n使出「绝影逝」，大踏步上前，劲力环绕，身形飘忽，虚影远逝，去势难料。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[PNK$n使出「飞无踪」，身形急速闪动，向前飞窜而出，眨眼间便了无踪迹。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[PNK$n一招「步天涯」，身形宛如蛟龙，翻转如电，以急速身法避开凌厉攻击。]],["id"]=3,["textColor"]=[[RAN]]}},["qibaotianlanwu"]={["1"]={["action"]=[[$n脚尖微一点地，一招RAN「金沙飞扬」NOR，躲过了$N的攻势。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$N眼见就要击中$n，只见$n忽的一闪，一招RAN「银光泛动」NOR悄然避开了。]],["id"]=2,["textColor"]=[[HIC]]},["3"]={["action"]=[[$n一招RAN「逆乘碧浪」NOR向后一仰，身体向后滑行，躲过了$n的招式。]],["id"]=3,["textColor"]=[[HIB]]},["4"]={["action"]=[[$n提身一纵，腾空而起，一招RAN「九天踏云」NOR，空中折转翻腾，落在了数丈之外。]],["id"]=4,["textColor"]=[[RAN]]},["5"]={["action"]=[[$n使出RAN「秋岚阵阵」NOR，身体不断转动，虚影连连，躲过了所有的招式。]],["id"]=5,["textColor"]=[[HIY]]},["6"]={["action"]=[[$n笑声连连，一招RAN「流光一瞬」NOR，身体向前倏的一冲，再看时，$n已在$N身后。]],["id"]=6,["textColor"]=[[HIR]]},["7"]={["action"]=[[$n沉声一喝，运起全身功力，一招RAN「天岚之舞」NOR，衣袂无风而动，狂沙绝地而起，遮盖了周遭数丈范围，$N攻击无法命中。]],["id"]=7,["textColor"]=[[HIM]]}},["qimenwuzhuan"]={["1"]={["action"]=[[但是$n身形有如流水，轻轻一转，一式RAN「水转」NOR，举重若轻的避开这一击。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[身随意转，脚踩玄门，一式RAN「地转」NOR，倏地平地转开了三尺，避过了这一招。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[可是$n侧身一让，使出六甲秘行中的RAN「风转」NOR，$N这一招扑了个空。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[却见$n足不点地，幻出五个身影，一式RAN「天转」NOR，往旁窜开数尺，躲了开去。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[身形微晃，使出奇门RAN「轮转」NOR，连续旋转到了$N的身后。]],["id"]=5,["textColor"]=[[CYN]]}},["qingfushenfa"]={["1"]={["action"]=[[只见$n一招「福满乾坤」，身形陡然纵起，躲过了$N这一招。]],["anim"]=[[qfsf_1]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-150,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式「五蝠献寿」，身形晃动，向一旁飘出，避开了$N这一招。]],["anim"]=[[qfsf_1]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-150,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出「洞天福地」，一个空心筋斗向后翻出，避开了$N的凌厉攻势。]],["anim"]=[[qfsf_2]],["hitPos"]=[[chest]],["id"]=3,["offset"]=-150,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一招「云龙百蝠」，身随意转，$N只觉眼前一花，$n已绕至$N的身后。]],["anim"]=[[qfsf_2]],["hitPos"]=[[chest]],["id"]=4,["offset"]=-150,["textColor"]=[[CYN]]}},["qiulinshiye"]={["1"]={["action"]=[[只见$n略一低头，形似弯腰拾叶，轻而易举的躲过$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[$n使出「大鹏展翅」，向一旁飘然纵出，轻轻着地。]],["id"]=10,["textColor"]=[[CYN]]},["11"]={["action"]=[[但是$n身形飘忽，轻轻一纵，早已避开。]],["id"]=11,["textColor"]=[[CYN]]},["12"]={["action"]=[[$n身随意转，倏地往一旁挪开了三尺，避过了这一招。]],["id"]=12,["textColor"]=[[CYN]]},["13"]={["action"]=[[可是$n侧身一让，$N这一招扑了个空。]],["id"]=13,["textColor"]=[[CYN]]},["14"]={["action"]=[[却见$n足不点地，往旁窜开数尺，躲了开去。]],["id"]=14,["textColor"]=[[CYN]]},["15"]={["action"]=[[$n身形微晃，有惊无险地避开了$N这一招.]],["id"]=15,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是$n目光流转，双肩微动，脚步轻移已避开了$N的攻击。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[然而$n微微移步向前，仿佛直走中宫却又飘忽不定，$N的攻势全部落空。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[但是$n身形如竹叶飞舞，随风绕着$N的出招飘动，好象要击中，却若无物。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[可是$n身随意转，仿佛闲庭散步，人却已在数丈以外，闪过了这一招。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n漫不经心的向左迈出一步，刚好避过$N的凌厉攻势。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[可是$n恰巧往右走了一步，躲过了$N这一招。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[只见$n一招「白鹤冲天」，身体向上笔直地纵起丈余，躲过了$N这一招。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n一个「鹞子翻身」，向后纵出数丈之远，避开了$N的凌厉攻势。]],["id"]=9,["textColor"]=[[CYN]]}},["qiuyannanhui"]={["1"]={["action"]=[[$n一式CYN「雁渡寒潭」NOR，身不倾，脚不移，身体如行云流水般直滑出丈余。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式CYN「平沙落雁」NOR，忽然一弯腰，全身贴地而行，顿时闪过了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式CYN「雁舞风堂」NOR，一转身间，四面八方飘动着无数个$n的身影，令$N手足无措。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式CYN「云雁惊厥」NOR，长袖一拂，全身化为一道白影，幽幽地从$N头顶飘落。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式CYN「雁影行洲」NOR，身体如陀螺般急转，登时一股气流涌出，令$N难以动弹。]],["id"]=5,["textColor"]=[[CYN]]}},["qixinghuanwei"]={["1"]={["action"]=[[$n一式RAN「摇光移步」NOR，前后脚脚尖脚跟相靠，身体如行云流水般滑出丈余。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式RAN「天璇掠波」NOR，双臂前伸，全身贴地平飞，顿时闪过了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式RAN「天玑换形」NOR，足不动，手不抬，一转眼间便绕到了$N的身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式RAN「开阳分身」NOR，一转身间，四面八方飘动着无数个$n的身影，令$N手无足措。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式RAN「玉衡落日」NOR，全身笔直，拔地而起，在半空中一转，已落到几丈远的地方。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n一式RAN「天权双飞」NOR，两臂鹏举如翼，在剌剌风声中，从$N头顶横跃而过。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n一式RAN「天枢出水」NOR，双脚点地，全身化为一道白影，急速绕着$N打了几转。]],["id"]=7,["textColor"]=[[CYN]]}},["qixingmizongbu"]={["1"]={["action"]=[[只见$n身随意转，一式「踏摇光」，向后翻出数尺，躲了开去。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n一式「冲玉衡」，身形暴涨，向前冲出两道残影，避开了$N的攻势。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n忽而围绕$N疾奔开来，好似星斗绕其旋转，身形难以捉摸。正式一招「破天玑」。]],["id"]=3,["textColor"]=[[RAN]]},["4"]={["action"]=[[$n左右横移，忽前忽后，$N只觉头晕目眩，满头星斗转个不停，一时不知如何是好。]],["id"]=4,["textColor"]=[[RAN]]}},["shaolinshenfa"]={["1"]={["action"]=[[$n一式「一苇渡江」，前后脚脚尖脚跟相靠，身体如行云流水般滑出丈余。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式「雨燕掠波」，双臂前伸，全身贴地平飞，顿时闪过了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式「移步换形」，足不动，手不抬，一转眼间便绕到了$N的身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式「分身化影」，一转身间，四面八方飘动着无数个$n的身影，令$N手无足措。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式「孤骛落日」，全身笔直，拔地而起，在半空中一转，已落到几丈远的地方。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n一式「鸿雁双飞」，两臂鹏举如翼，在剌剌风声中，从$N头顶横跃而过。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n一式「苍龙出水」，双脚点地，全身化为一道白影，急速绕着$N打了几转。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n一式「稚凤归巢」，身体如陀螺般急转，气流形成一个个漩涡，令$N陷身其间，动弹不得。]],["id"]=8,["textColor"]=[[CYN]]}},["shenxingbaibian"]={["1"]={["action"]=[[但是$n身形飘忽，轻轻一纵，轻而易举的避开这一击。]],["anim"]=[[dodge-sxbb_head]],["hitPos"]=[[head]],["id"]=1,["offset"]=-100,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n身随意转，向后空翻退开数尺，躲了开去。]],["anim"]=[[dodge-sxbb_chest]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-150,["textColor"]=[[RAN]]},["3"]={["action"]=[[只见$n迎招而上，谁知就在即将被打中时突然一个转折退到数尺之外。]],["anim"]=[[dodge-sxbb_foot]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-175,["textColor"]=[[RAN]]},["4"]={["action"]=[[但是$n身形飘忽，轻轻一纵，轻而易举的避开这一击。]],["anim"]=[[dodge-sxbb_head]],["hitPos"]=[[head]],["id"]=4,["offset"]=-125,["textColor"]=[[RAN]]},["5"]={["action"]=[[$n身随意转，向后空翻退开数尺，躲了开去。]],["anim"]=[[dodge-sxbb_chest]],["hitPos"]=[[chest]],["id"]=5,["offset"]=-175,["textColor"]=[[RAN]]},["6"]={["action"]=[[只见$n迎招而上，谁知就在即将被打中时突然一个转折退到数尺之外。]],["anim"]=[[dodge-sxbb_foot]],["hitPos"]=[[foot]],["id"]=6,["offset"]=-250,["textColor"]=[[RAN]]},["7"]={["action"]=[[但是$n身形飘忽，轻轻一纵，轻而易举的避开这一击。]],["anim"]=[[dodge-sxbb_head]],["hitPos"]=[[head]],["id"]=7,["offset"]=-150,["textColor"]=[[RAN]]},["8"]={["action"]=[[$n身随意转，向后空翻退开数尺，躲了开去。]],["anim"]=[[dodge-sxbb_chest]],["hitPos"]=[[chest]],["id"]=8,["offset"]=-200,["textColor"]=[[RAN]]},["9"]={["action"]=[[只见$n迎招而上，谁知就在即将被打中时突然一个转折退到数尺之外。]],["anim"]=[[dodge-sxbb_foot]],["hitPos"]=[[foot]],["id"]=9,["offset"]=-255,["textColor"]=[[RAN]]}},["shenxingkong"]={["1"]={["action"]=[[$n使出一招「心空」，身体向侧后飘去。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n使出一招「誓言空」，双足一点，跃至数丈之外。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出一招「莲空」，身形一变，滑至$N身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n大吼一声，使出一招「大安空」，从$N头顶越过。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n使出一招「佛空」，如轻鸿般飘去，瞬间又闪至$N面前。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n使出一招「金刚空」，顿时$N周围都是$n的身影。]],["id"]=6,["textColor"]=[[CYN]]}},["sheyao"]={["1"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[snake-dodge]],["hitPos"]=[[head]],["id"]=1,["offset"]=-199,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[snake-dodge]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-198,["textColor"]=[[CYN]]},["3"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[snake-dodge]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-197,["textColor"]=[[CYN]]}},["shizhenjue"]={["1"]={["action"]=[[$n虎步龙骧，一步当先，一招「一字长蛇」直接闪过了$N的攻击。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n脚尖一点，使出一招「二龙出水」，堪堪躲过$N的攻击。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n运气内劲，脚步轻点于地，身形向后一仰，一招「天地三才」使出，已落至$N数丈之外。]],["id"]=3,["textColor"]=[[RAN]]}},["shuishangpiao"]={["1"]={["action"]=[[$n足跟一支，全身后仰，一招「鲤鱼倒穿波」，反窜出丈余，躲过了$N的攻击。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n身体忽然柔若无骨，左右摇摆，使出一招「雨打漂萍」，避过了$N的攻击。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出「物换星移」，滴溜溜一个转身，从$N身旁擦身而过，反而到了$N身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一招「落叶随风」，身体如一片落叶一般飘了出去，身行之潇洒，迅速到了极处。]],["id"]=4,["textColor"]=[[CYN]]}},["sixiangbufa"]={["1"]={["action"]=[[只见$n一招「少阴步」，身体向上笔直地纵起丈余，躲过了$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一个「乾兑步」，向后纵出数丈之远，避开了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出「离震步」，向一旁飘然纵出，轻轻着地。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[但是$n身形飘忽，使出「少阳步」，轻轻一纵，早已避开。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n身随意转「太阴步」，倏地往一旁挪开了三尺，避过了这一招。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[可是$n侧身一让，一个「巽坎步」，$N这一招扑了个空。]],["id"]=6,["textColor"]=[[CYN]]}},["taixuangong"]={["1"]={["action"]=[[$n左手拍出，劲风到处，把$N震到一边。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n手臂回转，抓住$N手肘一推，将$N远远掷开。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n两腿轻蹬，激跃而出，竟已落在十数丈外。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$N只觉眼前一花，只见到$n身形一幌，自己的招数居然莫名其妙就落空了。]],["id"]=4,["textColor"]=[[CYN]]}},["taixuangong2"]={["1"]={["action"]=[[$n左手拍出，劲风到处，把$N震到一边。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n手臂回转，抓住$N手肘一推，将$N远远掷开。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n两腿轻蹬，激跃而出，竟已落在十数丈外。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$N只觉眼前一花，只见到$n身形一幌，自己的招数居然莫名其妙就落空了。]],["id"]=4,["textColor"]=[[CYN]]}},["takongxubu"]={["1"]={["action"]=[[$n一式「行云流水」，身不倾，脚不移，身体如行云流水般直滑出丈余。]],["anim"]=[[dodge-xktb_chest]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-110,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n一式「潜音夜行」，忽然一弯腰，全身贴地而行，顿时闪过了$N的凌厉攻势。]],["anim"]=[[dodge-xktb_foot]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式「移步换形」，足不动，手不抬，一转眼间便绕到了$N的身后。]],["anim"]=[[dodge-xktb_head]],["hitPos"]=[[head]],["id"]=3,["offset"]=-90,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式「分身化影」，一转身间，四面八方飘动着无数个$n的身影，令$N手足无措。]],["anim"]=[[dodge-xktb_chest]],["hitPos"]=[[chest]],["id"]=4,["offset"]=-160,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式「更上层楼」，身在空中，左脚在右足上一点，从$N头顶腾空而过。]],["anim"]=[[dodge-xktb_foot]],["hitPos"]=[[foot]],["id"]=5,["offset"]=-220,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n一式「仙子出水」，长袖一拂，全身化为一道白影，幽幽地从$N头顶飘落。]],["anim"]=[[dodge-xktb_head]],["hitPos"]=[[head]],["id"]=6,["offset"]=-90,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n一式「峰回路转」，身体如陀螺般急转，登时一股气流涌出，令$N难以动弹。]],["anim"]=[[dodge-xktb_chest]],["hitPos"]=[[chest]],["id"]=7,["offset"]=-180,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n一式「临行秋波」，身行倏的从$N的眼前直绕到身后，$N瞪大了两眼，不明所以。]],["anim"]=[[dodge-xktb_foot]],["hitPos"]=[[foot]],["id"]=8,["offset"]=-250,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n一式「浪子回头」，身行倏的从$N的眼前飘过，长发一甩，潇洒之极。]],["anim"]=[[dodge-xktb_head]],["hitPos"]=[[head]],["id"]=9,["offset"]=-150,["textColor"]=[[CYN]]}},["taxuewuhen"]={["1"]={["action"]=[[$n一式「雁落平沙」，变招奇速，右足向前踢出，身子已然腾起，轻轻巧巧地落在一旁。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式「玉龙飞起」，纵身高跃，半空中一折一转，已飘身在数丈之外。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式「夏日消融」，两足足跟不动，足尖左磨，身子随之右转，卸开了$N这一招。]],["anim"]=[[dodge-txwh_foot]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-180,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式「枯松倒挂」，只见$n身子后仰，双掌往地下一撑，身子借势倒射而出，$N便已打$n不着。]],["anim"]=[[dodge-txwh_foot]],["hitPos"]=[[foot]],["id"]=4,["offset"]=-220,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式「晴雪飞滩」，纵高伏低，东奔西闪，身形飘忽不定，$N手无足措，只得回招自守。]],["anim"]=[[dodge-txwh_chest]],["hitPos"]=[[chest]],["id"]=5,["offset"]=-89,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n一式「冰丝带雨」，突然反手一招，竟然是两败俱伤的打法，趁$N手忙脚乱安全脱身。]],["anim"]=[[dodge-txwh_chest]],["hitPos"]=[[chest]],["id"]=6,["offset"]=-110,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n一式「寒江钓雪」，不招不架，只微微一侧身，$N犹如暴风骤雨般的进攻便即落空。]],["anim"]=[[dodge-txwh_head]],["hitPos"]=[[head]],["id"]=7,["offset"]=-40,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n一式「鱼龙潜跃」，陡然间身形拔起，直冲云霄，直如鹰隼，几个盘旋，飘飘荡荡落在数丈之外。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n一式「踏雪无痕」，身形急速旋转，几下就划到数丈之外。]],["anim"]=[[dodge-txwh_foot]],["hitPos"]=[[foot]],["id"]=9,["offset"]=-250,["textColor"]=[[CYN]]}},["tianluobufa"]={["1"]={["action"]=[[$n一式「巨鹏亮翅」，两臂鹏举如翼，在剌剌风声中，从$N头顶横跃而过。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式「风送紫霞」，如一阵清风，舒缓地闪过了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式「燕回朝阳」，轻盈地一跃，一转眼间便绕到了$N的身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式「却别苍松」，一转身间，向后飘出近一丈远]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式「苍龙盘岭」，宛若一条矫矢苍龙，围着$N急速地盘旋了几圈。]],["id"]=5,["textColor"]=[[CYN]]}},["tianluodiwangshi"]={["1"]={["action"]=[[$n腰肢轻摆，就如一朵菊花在风中微微一颤，斜身移步，早已避开。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[$n身子向前一挺，飞也似的滑了开去，但见$n东滑西闪，左转右折，实无瞬息之间停留，$N的诸般招式一一落空。]],["id"]=10,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n展开轻功提纵术，犹如疾风掠地，忽来忽往，瞬息之间进退数次，於丈许方圆之内腾挪奔跃，令$N无从进招。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n顺著$N攻势避过，身形一幌，竟然在$N身边一掠而过，趋退若神，步子微挫，早已让开。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n脚步轻盈，身手迅捷，轻功施展得圆转如意，身法之快，异乎寻常，矫夭腾挪，轻轻巧巧地避过$N这一招。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[却见$n潇洒自如，足下微尘不起，轻飘飘的似是缓步而行，不疾不徐地避了开去，的是飘逸无伦，变化万方。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n展开问情宫轻功，奔驰来去，斜窜急转，纵横飘忽，令$N难以确定出手的方位。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n衣襟当风，飘飘然如欲乘风而去，越奔越是轻捷，飞舞来去，脚下全不着力，$N不禁暗感难以捉摸。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n双足一登，身子腾空而起，犹似燕子穿林一般，离地尺许，平平掠过，相形之下，$N的招数似乎倒来迟一步。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n展开问情宫轻功，身随意走，一起脚，急奔如电，$N竟然跟随不上，心下暗暗惊佩。]],["id"]=9,["textColor"]=[[CYN]]}},["tiannanbufa"]={["1"]={["action"]=[[只见$n一招「旱地拔葱」，身体向上笔直地纵起丈余，躲过了$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一个「雨燕归巢」，向后纵出数丈之远，避开了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出「破土而出」，向一旁飘然纵出，轻轻着地。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[但是$n身形飘忽，一招「无中生有」轻轻一纵，早已避开。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n身随意转，一招「乘风而去」倏地往一旁挪开了三尺，避过了这一招。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[可是$n侧身一让，一招「鲧化大鹏」$N这一招扑了个空。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[却见$n足不点地，一招「青云直上」往旁窜开数尺，躲了开去。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n身形微晃，一招「凤翔九天」有惊无险地避开了$N这一招。]],["id"]=8,["textColor"]=[[CYN]]}},["tiyunzong"]={["1"]={["action"]=[[只见$n一招「白鹤冲天」，身体向上笔直地纵起丈余，躲过了$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一个「鹞子翻身」，向后纵出数丈之远，避开了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出「大鹏展翅」，向一旁飘然纵出，轻轻着地。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[但是$n身形飘忽，轻轻一纵，早已避开。,]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n身随意转，倏地往一旁挪开了三尺，避过了这一招。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[可是$n侧身一让，$N这一招扑了个空。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[却见$n足不点地，往旁窜开数尺，躲了开去。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n身形微晃，有惊无险地避开了$N这一招。]],["id"]=8,["textColor"]=[[CYN]]}},["wudangmianyanbu"]={["1"]={["action"]=[[$n一招「穿宵掠云」，翻身一跃，退而求守，躲过了$N的攻势。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n一招「揽岳走星」，步伐忽快忽慢，忽急忽缓，既躲闪开攻势，又让$N困惑难攻。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n一招「飞鸟尽投」，双臂翻转如飞鸟盘旋，待将$N的杀招一躲又迅猛回头，始终让自己立于攻防兼备之地。]],["id"]=3,["textColor"]=[[RAN]]}},["wuduyanluobu"]={["1"]={["action"]=[[$n不慌不忙，一式「江水横流」，身行倏的向一旁平移数尺,堪堪躲过了$N的功势。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n身行如鬼魅般一晃，刹那间已远去数丈之外，$N顿时扑了个空。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n身行忽的加快，如一缕青烟般绕着$N飞快旋转，看得$N一阵头晕眼花，急忙收招跳开。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n怪异的一笑，身行忽的变得朦胧不清，$N的凌厉招式竟然透体而过，原来竟是一具幻影。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n的身行顿时变得如蛇一般柔软，随着$N的招式左右摆动，竟使得$N招招落空。]],["id"]=5,["textColor"]=[[CYN]]}},["wuhenjin"]={["1"]={["action"]=[[$n身形随心而动，运起无痕劲轻轻一纵，便避开这一击。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n不慌不忙，运无痕劲于双掌，待$N攻来之时，$n已借力往反向退开数尺，轻易躲过这一击。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n身随意转，迎着$N的攻击而上，一个转折又落回原地，而$N这一击没有碰到$n分毫。]],["id"]=3,["textColor"]=[[RAN]]}},["wuxingdun"]={["1"]={["action"]=[[但是$n身形有如流水，轻轻一闪，举重若轻的避开这一击。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[$n哈哈一笑，把手中的兵刃交错一击，喝道“看我HIY『金遁』NOR”，突然精光耀眼，$N眼前一花，这一招不知落到了何处。]],["id"]=10,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n身随意转，一式五行「木字决」，倏地从木门挪开了三尺，避过了这一招。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[可是$n侧身一让，使出五行身法中的「金字决」，$N这一招扑了个空。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[却见$n足不点地，幻出五个身影，从火门往旁窜开数尺，躲了开去。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n身形微晃，使出五行「土字决」，土遁到了$N的身后。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[可是$n微微一笑，$N眼前水雾弥漫，$n已使出HIC『水遁』NOR借水而逝。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[却见$n抛下手中兵刃，扑向路边的一棵大树，转眼和枝叶混为一体，$N茫然四顾，不知$n已经靠HIG『木遁』NOR躲开攻击。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n原地一转，立时钻入土中。$N这一招落到了空处，惊道HIY『土遁』NOR！]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n随手打出一团火球，喝道HIR『火遁』NOR！整个人消失在火球中。]],["id"]=9,["textColor"]=[[CYN]]}},["xiaoyaoyou"]={["1"]={["action"]=[[$n一个RAN「蜻蜓点水」NOR，躲过了$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n身形向后一纵，使出一招RAN「细胸巧翻云」NOR，避过了$N的攻击。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出RAN「虚怀若谷」NOR，恰好躲过了$N的攻势。]],["id"]=3,["textColor"]=[[CYN]]}},["yanlingshenfa"]={["1"]={["action"]=[[$n一式「单燕南飞」，左脚脚尖垫起，右脚凌空发力，身体如行云流水般滑出丈余。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式「一叶障目」，身行旋转，双脚跋地而起，顿时闪过了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式「燕南归巢」，身体如陀螺般急转，气流形成一个个漩涡，令$N陷身其间。]],["id"]=3,["textColor"]=[[CYN]]}},["yixingbufa"]={["1"]={["action"]=[[$n漫不经心的向左迈出一步，刚好避过$N的凌厉攻势。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[可是$n不紧不慢往右走了一步，躲过了$N这一招。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n看似无心地信手一拂，肩头微侧,堪堪避过了$N这一招。]],["id"]=3,["textColor"]=[[CYN]]}},["youlongshenfa"]={["1"]={["action"]=[[只见$n一招HIC「龙翔九天」NOR，右脚轻轻点地，身体HIC「嗖」NOR的向上笔直地纵起丈余，躲过了$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一个HIY「龙游四海」NOR，双臂一张，行云流水般向后纵出，避开了$N的凌厉攻势。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出MAG「翩若惊鸿」NOR，身形不住闪动，终于躲过$N的攻击。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n使出BLU「神龙无影」NOR，$N眼前一花，已不见$n踪影。]],["id"]=4,["textColor"]=[[CYN]]}},["yueyingwubu"]={["1"]={["action"]=[[$n身形一晃，纤腰一扭，一招RAN「星河鹭起」NOR，弹地而起。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一招RAN「歌尽桃花扇底风」NOR，$N只觉眼前一花，不见了$n的身影。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一招RAN「扫尽浮云风不定」NOR，身形微晃，有惊无险地避开了$N这一招。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[只见$n身子向后一翻，一招RAN「缥渺孤鸿影」NOR，后荡而起，掠向一旁。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一招RAN「起舞弄清影」NOR，长袖翻飞，躲过$N这一招。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[却见$nRAN「万顷江田一鹭飞」NOR，冲天而起，一波三折，端是美观。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[可是$n一个RAN「流水落花春去也」NOR，侧身一让，$N这一招扑了个空。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[只见$n一招RAN「月轮穿沼水无痕」NOR，倒掠身形，凌空两个翻转，退出两丈开外。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n息气上升，意存玉枕，一招RAN「月在青天影在波」NOR，身子飘然而起。]],["id"]=9,["textColor"]=[[CYN]]}},["yunlongshenfa"]={["1"]={["action"]=[[$n一式「龙腾虎跃」，身行一转，猛的跳向一旁,躲过了$N的功势。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[$n一式「九天揽月」，宛若一条矫矢苍龙，倏的拔地而起，令$N不敢仰视。]],["id"]=10,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一式「沙场点兵」，双臂置于身后，不急不缓，昂首从$N眼前跨过。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n一式「风雨同舟」，不退反进，一下子绕到了$N的身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一式「养精蓄锐」，缓缓的向后一退，轻松让过了$N的凌厉攻势。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n一式「无心插柳」，左手一扬，身行一晃，便向右飘出丈远。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n一式「苍鹰搏兔」，身体如一只苍鹰，呼的一声从$N的眼前飞过。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n一式「九龙在天」，忽的拔地而起，在半空中一转，已落到几丈远的地方。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n一式「瀑落九天」，全身化为一道白影，忽的一个空翻，从左边飘到右边。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[$n一式「幻眼云烟」，身形陡地变得飘忽不定，令$N无法看清。]],["id"]=9,["textColor"]=[[CYN]]}},["yunvshenfa"]={["1"]={["action"]=[[但是$n身形一转，使出「麝熏微度」，蓦地不见，避开了这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n一招「西施浣纱」，身随意转，倏地往一旁挪开了三尺。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n身形飘忽，瞻之在前，忽焉在后，却是「走马兰台」的身法。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n使出「洛河清波」，犹如在水面滑行一般，身形晃了开去。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[可是$n的身影飘飘渺渺，竟丝毫不着力，是一式「蓬山万重」的身法。]],["id"]=5,["textColor"]=[[CYN]]}},["zhaixinggong"]={["1"]={["action"]=[[$n一个「天外摘星」，跃起数尺，躲过了$N这一招。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n身形向后一纵，使出一招「飘然出尘」，避过了$N的攻击。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出「天狼涉水」，恰好躲过了$N的攻势。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一招「织女穿梭」，姿态美妙地躲了开去。]],["id"]=4,["textColor"]=[[CYN]]}},["zhizhuyao"]={["1"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[spider-dodge]],["hitPos"]=[[head]],["id"]=1,["offset"]=-199,["textColor"]=[[CYN]]},["2"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[spider-dodge]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-198,["textColor"]=[[CYN]]},["3"]={["action"]=[[但是被$p机灵地躲开了。]],["anim"]=[[spider-dodge]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-197,["textColor"]=[[CYN]]}},["zhongyueshenfeng"]={["1"]={["action"]=[[$n一式「风行中岳」，不退反进，全身忽地向前一纵，身行若风，恰好掠过$N的攻势。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n忽然全身在空中一扭、一转，两腿一个平飞，一式「山舞狂风」，把$N的攻击卷入满天身影之中。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n身形向上一飘，一只脚忽然轻踩在$N的身上，好一式「风在峻极」，遁在$N的身后。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n换变身形，整个身躯向上一抬一落，一招「风起云落」，虚实之间化去了$N的招式。]],["id"]=4,["textColor"]=[[CYN]]}},["zhutianhuashenbu"]={["1"]={["action"]=[[$n突然拔地而起，在空中一叠一转，飞到$N身后，实和武当绝技「借岳步云」有同工异曲之妙。]],["id"]=1,["textColor"]=[[CYN]]},["10"]={["action"]=[[$n脚下猛力一登，「天龙飞升」拔起丈高，逼开了$N的招式。]],["id"]=10,["textColor"]=[[CYN]]},["11"]={["action"]=[[$n双掌连拍，一式「龙飞九天」跃起三丈高，远远飘了开去。]],["id"]=11,["textColor"]=[[CYN]]},["12"]={["action"]=[[$n身子连续翻滚，一式「神龙降世」，跳出了$N的攻击范围。]],["id"]=12,["textColor"]=[[CYN]]},["13"]={["action"]=[[$n一招「海底游龙」，身子一弯，贴着地面平平滑开。]],["id"]=13,["textColor"]=[[CYN]]},["14"]={["action"]=[[只见$n一招「天地钩」，身体腾空，双足向上，笔直地纵起丈余，躲过了$N这一招。]],["id"]=14,["textColor"]=[[CYN]]},["15"]={["action"]=[[$n身随意转，一式「凤点头」头部前挺，侧身收腹，倏地往一旁挪开了三尺，避过了这一招。]],["id"]=15,["textColor"]=[[CYN]]},["16"]={["action"]=[[$n双足抓地，身形微晃，一招「鹰爪松」有惊无险地避开了$N这一招。]],["id"]=16,["textColor"]=[[CYN]]},["17"]={["action"]=[[但是$n身形飘忽，一式「风摆柳」，轻轻一纵，早已避开。]],["id"]=17,["textColor"]=[[CYN]]},["18"]={["action"]=[[$n一个「阴阳箭」，向后纵出数丈之远，避开了$N的凌厉攻势，立即又欺近$N身旁。]],["id"]=18,["textColor"]=[[CYN]]},["19"]={["action"]=[[$n使出「日月扣」，双手如钩向一旁飘然纵出，轻轻着地。]],["id"]=19,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n脚下连登，一招「升龙式」接连跃起三此，远远飘了开去。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n做了个「凤点头」的姿势，却又双袖挥动，轻轻向后滑出。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n一个「凤凰双飞」，身形随着$N的攻势轻轻飘起，从容躲过这一招。]],["id"]=4,["textColor"]=[[CYN]]},["5"]={["action"]=[[$n使出一招「玉凤穿云」，脚尖一点，身子拔高丈余，结果$N扑了个空。]],["id"]=5,["textColor"]=[[CYN]]},["6"]={["action"]=[[$n身形一摇，幻出无数个人影，一招「百鸟朝凤」躲过了$N的攻势。]],["id"]=6,["textColor"]=[[CYN]]},["7"]={["action"]=[[$n一招「飞凤天翔」纵身跃起，在空中一转，倏忽已落至$N身后。]],["id"]=7,["textColor"]=[[CYN]]},["8"]={["action"]=[[$n左一摇，右一晃，一招「云凤雾凰」已轻松闪过$N的攻击。]],["id"]=8,["textColor"]=[[CYN]]},["9"]={["action"]=[[却见$n的身形顺着$N的招式幻化不定，跟着「凤凰展翅」一转便到了$N的身后]],["id"]=9,["textColor"]=[[CYN]]}},["zuixianwangyuebu"]={["1"]={["action"]=[[但是$n身形飘忽，轻轻一纵，一招HIG「醉仙望月」NOR，轻而易举的避开这一击。]],["anim"]=[[barehand-dodge-head2]],["hitPos"]=[[head]],["id"]=1,["offset"]=-1,["textColor"]=[[RAN]]},["2"]={["action"]=[[$n身随意转，一式HIW「仙人敬酒」NOR，往旁窜开数尺，躲了开去。]],["anim"]=[[barehand-dodge-chest2]],["hitPos"]=[[chest]],["id"]=2,["offset"]=-100,["textColor"]=[[RAN]]},["3"]={["action"]=[[$n身形往上拔起，一招HIB「把酒飞仙」NOR，一个转折落在数尺之外。]],["anim"]=[[barehand-dodge-foot3]],["hitPos"]=[[foot]],["id"]=3,["offset"]=-120,["textColor"]=[[RAN]]}}}00